// Copyright (c) 2026 Roshan. All rights reserved.// Proprietary license — see LICENSE file for details.package com.roshan.persona.agent.ladbimport timber.log.Timberimport java.io.DataInputStreamimport java.io.DataOutputStreamimport java.io.IOExceptionimport java.net.Socketimport java.nio.ByteBufferimport java.nio.ByteOrderimport java.security.MessageDigestimport javax.crypto.Cipherimport javax.crypto.spec.IvParameterSpecimport javax.crypto.spec.SecretKeySpecimport javax.inject.Injectimport javax.inject.Singleton/** * NOUS — LADB Protocol (Module 9 v2 — audit P1). * * Encodes/decodes the ADB binary protocol for wireless debugging automation. * * ## ADB Protocol Summary * * ADB uses a simple binary protocol over TCP: * * ``` * ┌───────────┬──────────┬──────────┬──────────────┬─────────┐ * │ command   │ arg0     │ arg1     │ data_length  │ data_crc │ checksum * │ (4 bytes) │ (4 bytes)│ (4 bytes)│ (4 bytes)    │ (4 bytes)│ (4 bytes) * └───────────┴──────────┴──────────┴──────────────┴─────────┘ * │ magic     │  ← XOR of command with 0xFFFFFFFF (integrity check) * │ (4 bytes) │ * └───────────┘ * ``` * * Total header = 24 bytes (command + arg0 + arg1 + data_length + data_crc + magic). * * ## Commands used by NOUS * *  - **CNXN** — initial connection handshake. *  - **AUTH** — authentication (1 = RSA token, 2 = signature). *  - **OPEN** — open a new stream (e.g., `shell:input tap 500 500`). *  - **WRTE** — write data to an open stream. *  - **OKAY** — acknowledge receipt of WRTE. *  - **CLSE** — close a stream. * * @see <a href="https://android.googlesource.com/platform/system/adb/+/refs/heads/master/protocol.txt">ADB Protocol Spec</a> */@Singletonclass LadbProtocol @Inject constructor() {    /** ADB command codes (4-byte ASCII, stored as int). */    object Commands {        const val CNXN: Int = 0x4e584e43  // "CNXN"        const val AUTH: Int = 0x48545541  // "AUTH"        const val OPEN: Int = 0x4e45504f  // "OPEN"        const val WRTE: Int = 0x45545257  // "WRTE"        const val OKAY: Int = 0x59414b4f  // "OKAY"        const val CLSE: Int = 0x45534c43  // "CLSE"    }    /** ADB protocol version + max payload size. */    object Versions {        const val A_VERSION: Int = 0x01000000  // v1        const val MAX_PAYLOAD: Int = 1024 * 1024  // 1 MB    }    /**     * Encode an ADB message header (24 bytes).     *     * @param command command code (e.g., [Commands.OPEN]).     * @param arg0 first argument (e.g., stream ID for OPEN).     * @param arg1 second argument.     * @param payload the data payload (used to compute CRC + length).     * @return 24-byte header.     */    fun encodeHeader(command: Int, arg0: Int, arg1: Int, payload: ByteArray): ByteArray {        val buf = ByteBuffer.allocate(24).order(ByteOrder.LITTLE_ENDIAN)        buf.putInt(command)        buf.putInt(arg0)        buf.putInt(arg1)        buf.putInt(payload.size)        buf.putInt(crc32(payload))        buf.putInt(command xor 0xFFFFFFFF.toInt())  // magic        return buf.array()    }    /**     * Send an ADB message (header + payload) over the socket.     */    @Throws(IOException::class)    fun sendMessage(        output: DataOutputStream,        command: Int,        arg0: Int,        arg1: Int,        payload: ByteArray = ByteArray(0),    ) {        val header = encodeHeader(command, arg0, arg1, payload)        output.write(header)        if (payload.isNotEmpty()) {            output.write(payload)        }        output.flush()    }    /**     * Read an ADB message header from the socket.     *     * @return a [MessageHeader] with command/arg0/arg1/payloadLength, or null on EOF.     */    @Throws(IOException::class)    fun readHeader(input: DataInputStream): MessageHeader? {        val headerBytes = ByteArray(24)        val read = try {            input.read(headerBytes)        } catch (e: IOException) {            return null        }        if (read < 24) return null        val buf = ByteBuffer.wrap(headerBytes).order(ByteOrder.LITTLE_ENDIAN)        val command = buf.int        val arg0 = buf.int        val arg1 = buf.int        val payloadLength = buf.int        val payloadCrc = buf.int        val magic = buf.int        // Verify magic (should be command XOR 0xFFFFFFFF).        if (magic != (command xor 0xFFFFFFFF.toInt())) {            Timber.tag(TAG).w("Magic mismatch: got 0x${Integer.toHexString(magic)}, expected 0x${Integer.toHexString(command xor 0xFFFFFFFF.toInt())}")            return null        }        return MessageHeader(command, arg0, arg1, payloadLength, payloadCrc)    }    /**     * Read the payload bytes following a header.     */    @Throws(IOException::class)    fun readPayload(input: DataInputStream, length: Int): ByteArray {        if (length <= 0) return ByteArray(0)        val payload = ByteArray(length)        input.readFully(payload)        return payload    }    /**     * Build the CNXN payload — system identity string.     *     * Format: `host::\0` (NOUS identifies as a host).     */    fun buildCnxnPayload(): ByteArray {        return "host::\u0000".toByteArray(Charsets.UTF_8)    }    /**     * Build the OPEN payload — shell command to execute.     *     * Format: `shell:<command>\0`     */    fun buildShellOpenPayload(command: String): ByteArray {        return "shell:$command\u0000".toByteArray(Charsets.UTF_8)    }    /** Compute CRC32 checksum (used by ADB protocol). */    private fun crc32(data: ByteArray): Int {        val crc = java.util.zip.CRC32()        crc.update(data)        return crc.value.toInt()    }    /** Decoded ADB message header. */    data class MessageHeader(        val command: Int,        val arg0: Int,        val arg1: Int,        val payloadLength: Int,        val payloadCrc: Int,    )    private companion object {        private const val TAG = "LadbProtocol"    }}